module uart_tx_data(
	Clk,
	Reset_n,
	Tx_Go,
	Trans_Done,
	uart_tx,
	type_flag,
	Data,
	Send_Go,
	Tx_done);

	//---Ports declearation: generated by Robei---
	input Clk;
	input Reset_n;
	input Tx_Go;
	output Trans_Done;
	output uart_tx;
	input [7:0] type_flag;
	output [7:0] Data;
	output Send_Go;
	input Tx_done;

	wire Clk;
	wire Reset_n;
	wire Tx_Go;
	reg Trans_Done;
	wire uart_tx;
	wire [7:0] type_flag;
	reg [7:0] Data;
	reg Send_Go;
	wire Tx_done;

	//----Code starts here: integrated by Robei-----
	    //Trans_Done的作用是增加代码的可构性，发送完指令后，对Trans_Done拉高，这个接口主要用来给做扩展设计的。
	   
	   
	   
	    wire Trans_Go;
	    wire[71:0]Data72 = "n\r\2OPS+TA";    
	    wire [79:0]Data80 = "n\r\TRAEH+TA";
	    
		reg test_en_dly1;
		reg test_en_dly2;
		
		//按键信号打拍
		always@(posedge Clk)
		begin
			test_en_dly1 <= Tx_Go;
			test_en_dly2 <= test_en_dly1;
		end
	
	  //控制发送使能
		assign Trans_Go = test_en_dly1 & !test_en_dly2;
	
	   //需要发送的指令字符，读取血氧的指令为AT+SPO2\r\n,读取血氧的指令为AT+HEART\r\n
	   //需要增加字符的，可以增加Data的位宽
	    
		//通过状态机的方式，将数据发送出去
	    reg [4:0]state;
	    always@(posedge Clk or negedge Reset_n)
	    if(!Reset_n)begin
	        state <= 0;
	        Data <= 0;
	        Send_Go <= 0; 
	        Trans_Done <= 0;
	    end
	    else begin
	        case(state)
	            0:
	            begin
	                Trans_Done <= 0;
	                if(Trans_Go == 1'b1 && type_flag == 8'd1)begin
	                    Data <= Data72[7:0];
	                    Send_Go <= 1; 
	                    state <= 1;     
	                end
	                else if(Trans_Go == 1'b1 && type_flag == 8'd2)begin
	                    Data <= Data80[7:0];
	                    Send_Go <= 1; 
	                    state <= 11;     
	                end
	                else begin
	                    Data <= Data;
	                    Send_Go <= 0; 
	                    state <= 0;         
	                end
	           end
	               
	           1:
	            begin
	                if(Tx_done)begin
	                    Data <= Data72[15:8];
	                    Send_Go <= 1;
	                    state <= 2;
	                end
	                else begin
	                    Data <= Data;
	                    Send_Go <= 0;
	                    state <= 1;
	                end
	            end
	            
	            2:
	            begin
	                if(Tx_done)begin
	                    Data <= Data72[23:16];
	                    Send_Go <= 1;
	                    state <= 3;
	                end
	                else begin
	                    Data <= Data;
	                    Send_Go <= 0;
	                    state <= 2;
	                end
	            end 
	              
	            3:
	            begin
	                if(Tx_done)begin
	                    Data <= Data72[31:24];
	                    Send_Go <= 1;
	                    state <= 4;
	                end
	                else begin
	                    Data <= Data;
	                    Send_Go <= 0;
	                    state <= 3;
	                end
	            end  
	                   
	            4:
	            begin
	                if(Tx_done)begin
	                    Data <= Data72[39:32];
	                    Send_Go <= 1;
	                    state <= 5;
	                end
	                else begin
	                    Data <= Data;
	                    Send_Go <= 0;
	                    state <= 4;
	                end
	            end  
	            
	            5:
	            begin
	                if(Tx_done)begin
	                    Data <= Data72[47:40];
	                    Send_Go <= 1;
	                    state <= 6;
	                end
	                else begin
	                    Data <= Data;
	                    Send_Go <= 0;
	                    state <= 5;
	                end
	            end              
	            
	            6:
	            begin
	                if(Tx_done)begin
	                    Data <= Data72[55:48];
	                    Send_Go <= 1;
	                    state <= 7;
	                end
	                else begin
	                    Data <= Data;
	                    Send_Go <= 0;
	                    state <= 6;
	                end
	            end             
	            
	            7:
	            begin
	                if(Tx_done)begin
	                    Data <= Data72[63:56];
	                    Send_Go <= 1;
	                    state <= 8;
	                end
	                else begin
	                    Data <= Data;
	                    Send_Go <= 0;
	                    state <= 7;
	                end
	            end           
	
	            8:
	            begin
	                if(Tx_done)begin
	                    Data <= Data72[71:64];
	                    Send_Go <= 1;
	                    state <= 9;
	                end
	                else begin
	                    Data <= Data;
	                    Send_Go <= 0;
	                    state <= 8;
	                end
	            end     
	                                
	            9:
	            begin
	                if(Tx_done)begin
	                    Send_Go <= 0;
	                    Trans_Done <= 1;
	                    state <= 0;
	                end
	                else begin
	                    Data <= Data;
	                    Send_Go <= 0;
	                    state <= 9;
	                end
	            end 
	            
	            11:
	            begin
	                if(Tx_done)begin
	                    Data <= Data80[15:8];
	                    Send_Go <= 1;
	                    state <= 12;
	                end
	                else begin
	                    Data <= Data;
	                    Send_Go <= 0;
	                    state <= 11;
	                end
	            end
	            
	            12:
	            begin
	                if(Tx_done)begin
	                    Data <= Data80[23:16];
	                    Send_Go <= 1;
	                    state <= 13;
	                end
	                else begin
	                    Data <= Data;
	                    Send_Go <= 0;
	                    state <= 12;
	                end
	            end 
	              
	            13:
	            begin
	                if(Tx_done)begin
	                    Data <= Data80[31:24];
	                    Send_Go <= 1;
	                    state <= 14;
	                end
	                else begin
	                    Data <= Data;
	                    Send_Go <= 0;
	                    state <= 13;
	                end
	            end  
	                   
	            14:
	            begin
	                if(Tx_done)begin
	                    Data <= Data80[39:32];
	                    Send_Go <= 1;
	                    state <= 15;
	                end
	                else begin
	                    Data <= Data;
	                    Send_Go <= 0;
	                    state <= 14;
	                end
	            end  
	            
	            15:
	            begin
	                if(Tx_done)begin
	                    Data <= Data80[47:40];
	                    Send_Go <= 1;
	                    state <= 16;
	                end
	                else begin
	                    Data <= Data;
	                    Send_Go <= 0;
	                    state <= 15;
	                end
	            end              
	            
	            16:
	            begin
	                if(Tx_done)begin
	                    Data <= Data80[55:48];
	                    Send_Go <= 1;
	                    state <= 17;
	                end
	                else begin
	                    Data <= Data;
	                    Send_Go <= 0;
	                    state <= 16;
	                end
	            end             
	            
	            17:
	            begin
	                if(Tx_done)begin
	                    Data <= Data80[63:56];
	                    Send_Go <= 1;
	                    state <= 18;
	                end
	                else begin
	                    Data <= Data;
	                    Send_Go <= 0;
	                    state <= 17;
	                end
	            end           
	
	            18:
	            begin
	                if(Tx_done)begin
	                    Data <= Data80[71:64];
	                    Send_Go <= 1;
	                    state <= 19;
	                end
	                else begin
	                    Data <= Data;
	                    Send_Go <= 0;
	                    state <= 18;
	                end
	            end     
	            
	            19:
	            begin
	                if(Tx_done)begin
	                    Data <= Data80[79:72];
	                    Send_Go <= 1;
	                    state <= 20;
	                end
	                else begin
	                    Data <= Data;
	                    Send_Go <= 0;
	                    state <= 19;
	                end
	            end
	                                
	            20:
	            begin
	                if(Tx_done)begin
	                    Send_Go <= 0;
	                    Trans_Done <= 1;
	                    state <= 0;
	                end
	                else begin
	                    Data <= Data;
	                    Send_Go <= 0;
	                    state <= 20;
	                end
	            end
	            
	            default:   
	                begin
	                    Data <= Data;
	                    Send_Go <= 0;
	                    state <= 0;
	                end
	        endcase
	    end
	    
	
	
	
	//---Module instantiation---
	uart_byte_tx uart_byte_tx1(
		.Clk(Clk),
		.Reset_n(Reset_n),
		.Data(Data),
		.Send_Go(Send_Go),
		.Baud_set(3'd5),
		.uart_tx(uart_tx),
		.Tx_done(Tx_done));

endmodule    //uart_tx_data

